local EasyFind = EasyFind
local ns = EasyFind and EasyFind._ns
if not ns then return end

-- Named creatures on WoW Forever: level, rank, how each faction sees them
-- and where they stand. Generated by dev/tools/npc_catalog.py;
-- do not edit by hand.
if not (ns.Caps and ns.Caps.forever) then return end

local names = {
    enUS = "",
    deDE = "",
    esES = "",
    esMX = "",
    frFR = "",
    itIT = "",
    koKR = "",
    ptBR = "",
    ruRU = "",
    zhCN = "",
    zhTW = "",
}
local titles = {
    enUS = "",
    deDE = "",
    esES = "",
    esMX = "",
    frFR = "",
    itIT = "",
    koKR = "",
    ptBR = "",
    ruRU = "",
    zhCN = "",
    zhTW = "",
}
local here = GetLocale and GetLocale() or "enUS"
-- A blank line in a locale falls back: esMX to esES, any to English.
local base = here == "esMX" and "esES" or nil
ns.NPC_DATA = {
    rows = "",
    names = names.enUS, titles = titles.enUS,
    localNames = here ~= "enUS" and names[here] or nil,
    localTitles = here ~= "enUS" and titles[here] or nil,
    baseNames = base and names[base] or nil,
    baseTitles = base and titles[base] or nil,
}
